// @vitest-environment node
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync} from "node:fs";import path from "node:path";import {build} from "vite";import {expect,test} from "vitest";import {createBuildConfig} from "./buildConfig";import {initialChunks,initialBytes,budgetPass,type ChunkMetric} from "./metrics";
async function fixture(entry:string){const root=mkdtempSync(path.join(process.cwd(),"bundle-case-"));mkdirSync(path.join(root,"src"));writeFileSync(path.join(root,"package.json"),'{"type":"module"}');writeFileSync(path.join(root,"index.html"),'<div id="root"></div><script type="module" src="/src/entry.ts"></script>');writeFileSync(path.join(root,"src/entry.ts"),entry);writeFileSync(path.join(root,"src/report.ts"),'export function report(){return "REPORT_LAZY_SENTINEL";}');writeFileSync(path.join(root,"src/icons.ts"),'export function home(){return "HOME_KEPT_SENTINEL";}export function unused(){return "UNUSED_REMOVED_SENTINEL";}');await build({...createBuildConfig(root),logLevel:"silent"});const chunks=JSON.parse(readFileSync(path.join(root,"dist/bundle-report.json"),"utf8")) as ChunkMetric[];const code=(selected:readonly ChunkMetric[])=>selected.map(chunk=>readFileSync(path.join(root,"dist",chunk.fileName),"utf8")).join("\n");return {root,chunks,code,entry:chunks.find(chunk=>chunk.isEntry)!.fileName};}
test("dynamiczny ekran nie trafia do statycznego grafu startu",async()=>{const output=await fixture('document.body.onclick=async()=>{const {report}=await import("./report");document.body.textContent=report();};');const initial=initialChunks(output.chunks,output.entry);expect(output.chunks.some(chunk=>chunk.dynamicImports.length>0)).toBe(true);expect(output.code(initial)).not.toContain("REPORT_LAZY_SENTINEL");expect(output.code(output.chunks)).toContain("REPORT_LAZY_SENTINEL");expect(readFileSync(path.join(output.root,"dist/bundle-report.html"),"utf8")).toContain("Mapa chunków");expect(readFileSync(path.join(output.root,"dist/.vite/manifest.json"),"utf8")).toContain("isDynamicEntry");},30000);
test("import statyczny włącza moduł do domknięcia startowego",async()=>{const output=await fixture('import {report} from "./report";document.body.textContent=report();');expect(output.code(initialChunks(output.chunks,output.entry))).toContain("REPORT_LAZY_SENTINEL");},30000);
test("nieużywany eksport ESM znika przy bezpośrednim imporcie",async()=>{const output=await fixture('import {home} from "./icons";document.body.textContent=home();');const code=output.code(output.chunks);expect(code).toContain("HOME_KEPT_SENTINEL");expect(code).not.toContain("UNUSED_REMOVED_SENTINEL");},30000);
test("dynamiczny wybór namespace zachowuje wszystkie możliwe eksporty",async()=>{const output=await fixture('import * as icons from "./icons";const name=document.body.dataset.icon==="unused"?"unused":"home";document.body.textContent=icons[name]();');expect(output.code(output.chunks)).toContain("UNUSED_REMOVED_SENTINEL");},30000);
test("raport mierzy rzeczywiste bajty i oddziela kompresję",async()=>{const output=await fixture('import {home} from "./icons";document.body.textContent=home();');for(const chunk of output.chunks){expect(chunk.raw).toBe(Buffer.byteLength(output.code([chunk])));expect(chunk.gzip).toBeGreaterThan(0);expect(chunk.brotli).toBeGreaterThan(0);}expect(initialBytes(output.chunks,output.entry)).toBeGreaterThan(0);expect(budgetPass(initialBytes(output.chunks,output.entry),100000)).toBe(true);expect(budgetPass(initialBytes(output.chunks,output.entry),0)).toBe(false);},30000);
test("rzeczywista aplikacja React ma vendor oraz leniwy ekran",async()=>{await build({...createBuildConfig(process.cwd()),logLevel:"silent"});const chunks=JSON.parse(readFileSync(path.join(process.cwd(),"dist/bundle-report.json"),"utf8")) as ChunkMetric[];const entry=chunks.find(chunk=>chunk.isEntry)!;expect(chunks.some(chunk=>chunk.fileName.includes("react-vendor"))).toBe(true);const code=initialChunks(chunks,entry.fileName).map(chunk=>readFileSync(path.join(process.cwd(),"dist",chunk.fileName),"utf8")).join("\n");expect(code).not.toContain("REPORT_SCREEN_ONLY");},30000);

